/**
 * H3: pathfinding on a CS2 nav mesh (any map), for the LIVE AI and the Core's WalkQuery. docs/nav.md "CS2 nav".
 *
 * The map package's `nav.json` (tools/build-map.ts, from the map's `.nav`) holds CS2's own nav: convex polygons
 * (areas) with directed connections per edge, generated by Valve from the full collision (clips included) for a
 * 32-unit hull, so a point inside an area is where a standing player fits. This module answers what the AI asks of
 * a nav (`MapNav` in src/sim2d/map-nav.ts, implemented structurally):
 *
 * - `areaAt` / `isWalkable` / `zAt` / `floorsAt`: point-in-polygon (2D, closed, `INSIDE_EPS`) and the polygon's
 *   height (fan triangulation from corner 0), the level nearest to the point's z when areas stack;
 * - `path(a, b)`: A* over areas (costs between the points where the walk crosses each connection: the portal's
 *   midpoint; 3D lengths; a jump link costs `JUMP_COST` more), then a funnel (string pull) through the portals,
 *   shrunk `PORTAL_INSET` from their ends, with every jump portal kept as a waypoint (the bot has to be there to
 *   jump); points carry the floor's z;
 * - `segmentWalkable(a, b)`: the straight line stays on connected areas, crossing walk and drop links (never a jump up);
 * - `escapeSpot`: the nearest way out of a blast by walking distance (Dijkstra over areas);
 * - sites and spawns from the map package's `map.json` (`MapInfo`).
 *
 * Links: a connection whose far side is higher than `STEP_UP` at the portal is a **jump** (only if at most
 * `JUMP_UP`, else unusable); one lower than `STEP_UP` is a **drop** (any height); ladders are parsed but not used
 * (the movement has no ladders yet, docs/movement.md). Deterministic: integer-indexed arrays, ties by area index,
 * no object-key iteration, IEEE-exact arithmetic only.
 */
import { bombsiteAt, roundNumber, type MapInfo, type Team, type Vec3 } from '../../contracts/index';

export const CS2_NAV_FORMAT = 'cs2-round-replay/cs2-nav@1';

/** Point-in-polygon tolerance (units): the nav's shared edges are exact, so this only absorbs rounding. */
const INSIDE_EPS = 0.5;
/** A step a hull walks up without jumping (Source sv_stepsize 18) plus slope slack along a portal. */
export const STEP_UP = 20;
/** Highest jump link (a CS2 crouch jump clears about 64 units). */
export const JUMP_UP = 62;
/** A jump link's far side must be within this of the portal (units; a standing jump carries a hull ~40 forward while rising). */
export const JUMP_REACH = 32;
/** Extra A* cost of a jump link (units): a bot prefers a short walk round to a jump. */
const JUMP_COST = 160;
/** Portal ends are pulled in this far (or to the portal's middle) so paths keep off corners. */
const PORTAL_INSET = 8;
/** Areas whose height at a point is this far from the asked z still match without a closer one (units). */
const LEVEL_SLACK = 40;
const GRID = 64;
/** segmentWalkable's sample spacing (units; the narrowest nav polygons are wider). */
const WALK_SAMPLE = 4;
/** A straight walk may cross this much empty space (units) between an area and one it drops to. */
const DROP_GAP = 40;

/** `nav.json`: corners are shared (xyz, 1/1000 unit); per area: [id, flags, corner indices, area ids per edge]. */
export interface Cs2NavJson {
  readonly format: string;
  readonly map: string;
  readonly source: { readonly file: string; readonly sha256: string; readonly version: number };
  readonly corners: readonly number[];
  readonly areas: readonly (readonly [number, number, readonly number[], readonly (readonly number[])[]])[];
  readonly ladders: readonly { readonly id: number; readonly top: readonly number[]; readonly bottom: readonly number[]; readonly width: number }[];
}

/** Nav attribute bits used here (VRF NavAttributeFlags). */
export const NAV_CROUCH = 0x10000;

export type LinkKind = 'walk' | 'drop' | 'jump';

interface Portal {
  readonly to: number;
  readonly kind: LinkKind;
  /** Portal segment (shrunk), its midpoint; z on the near and far side at the midpoint. */
  readonly ax: number;
  readonly ay: number;
  readonly bx: number;
  readonly by: number;
  readonly mx: number;
  readonly my: number;
  readonly zFrom: number;
  readonly zTo: number;
}

interface Area {
  readonly index: number;
  readonly id: number;
  readonly flags: number;
  readonly xs: Float64Array;
  readonly ys: Float64Array;
  readonly zs: Float64Array;
  readonly minX: number;
  readonly minY: number;
  readonly maxX: number;
  readonly maxY: number;
  readonly cx: number;
  readonly cy: number;
  readonly cz: number;
  readonly area: number;
  /** Connections, in file order (edge by edge). */
  portals: Portal[];
}

class Heap {
  private keys: number[] = [];
  private ids: number[] = [];
  get size(): number {
    return this.ids.length;
  }
  push(key: number, id: number): void {
    const k = this.keys;
    const v = this.ids;
    let i = v.length;
    k.push(key);
    v.push(id);
    while (i > 0) {
      const p = (i - 1) >> 1;
      if ((k[p] as number) < key || ((k[p] as number) === key && (v[p] as number) <= id)) break;
      k[i] = k[p] as number;
      v[i] = v[p] as number;
      i = p;
    }
    k[i] = key;
    v[i] = id;
  }
  pop(): number {
    const k = this.keys;
    const v = this.ids;
    const top = v[0] as number;
    const lk = k.pop() as number;
    const lv = v.pop() as number;
    const n = v.length;
    if (n > 0) {
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        if (l >= n) break;
        const r = l + 1;
        let c = l;
        if (r < n && ((k[r] as number) < (k[l] as number) || ((k[r] as number) === (k[l] as number) && (v[r] as number) < (v[l] as number)))) c = r;
        if ((k[c] as number) > lk || ((k[c] as number) === lk && (v[c] as number) >= lv)) break;
        k[i] = k[c] as number;
        v[i] = v[c] as number;
        i = c;
      }
      k[i] = lk;
      v[i] = lv;
    }
    return top;
  }
}

function cross(ax: number, ay: number, bx: number, by: number, px: number, py: number): number {
  return (bx - ax) * (py - ay) - (by - ay) * (px - ax);
}

export class Cs2NavError extends Error {
  override readonly name = 'Cs2NavError';
}

export class Cs2Nav {
  readonly map: string;
  readonly info: MapInfo | null;
  private readonly areas: Area[];
  private readonly cells = new Map<number, number[]>();
  private readonly gx0: number;
  private readonly gy0: number;
  /** Jump portal midpoints a path goes through, by "x,y" (the AI presses JUMP at them). */
  private readonly jumpPoints = new Set<string>();
  readonly ladderCount: number;

  constructor(json: Cs2NavJson, info: MapInfo | null) {
    if (json.format !== CS2_NAV_FORMAT) throw new Cs2NavError(`nav.json: expected format ${CS2_NAV_FORMAT}`);
    this.map = json.map;
    this.info = info;
    this.ladderCount = json.ladders.length;
    const c = json.corners;
    const byId = new Map<number, number>();
    this.areas = json.areas.map((a, index) => {
      const [id, flags, ci] = a;
      if (ci.length < 3) throw new Cs2NavError(`nav.json: area ${id} has ${ci.length} corners`);
      const n = ci.length;
      const xs = new Float64Array(n);
      const ys = new Float64Array(n);
      const zs = new Float64Array(n);
      for (let k = 0; k < n; k++) {
        const v = ci[k] as number;
        xs[k] = c[v * 3] as number;
        ys[k] = c[v * 3 + 1] as number;
        zs[k] = c[v * 3 + 2] as number;
      }
      let minX = Infinity;
      let minY = Infinity;
      let maxX = -Infinity;
      let maxY = -Infinity;
      for (let k = 0; k < n; k++) {
        minX = Math.min(minX, xs[k] as number);
        maxX = Math.max(maxX, xs[k] as number);
        minY = Math.min(minY, ys[k] as number);
        maxY = Math.max(maxY, ys[k] as number);
      }
      // Area-weighted centroid (fan from corner 0).
      let w = 0;
      let sx = 0;
      let sy = 0;
      for (let k = 1; k + 1 < n; k++) {
        const t = cross(xs[0] as number, ys[0] as number, xs[k] as number, ys[k] as number, xs[k + 1] as number, ys[k + 1] as number) / 2;
        w += t;
        sx += (t * ((xs[0] as number) + (xs[k] as number) + (xs[k + 1] as number))) / 3;
        sy += (t * ((ys[0] as number) + (ys[k] as number) + (ys[k + 1] as number))) / 3;
      }
      let cx = minX + (maxX - minX) / 2;
      let cy = minY + (maxY - minY) / 2;
      if (Math.abs(w) > 1e-9) {
        cx = sx / w;
        cy = sy / w;
      }
      if (byId.has(id)) throw new Cs2NavError(`nav.json: duplicate area id ${id}`);
      byId.set(id, index);
      const area: Area = { index, id, flags, xs, ys, zs, minX, minY, maxX, maxY, cx, cy, cz: 0, area: Math.abs(w), portals: [] };
      return { ...area, cz: polyZ(area, cx, cy) };
    });
    this.gx0 = Math.floor(Math.min(...this.areas.map((a) => a.minX)) / GRID);
    this.gy0 = Math.floor(Math.min(...this.areas.map((a) => a.minY)) / GRID);
    for (const a of this.areas) {
      for (let j = Math.floor(a.minY / GRID); j <= Math.floor(a.maxY / GRID); j++) {
        for (let i = Math.floor(a.minX / GRID); i <= Math.floor(a.maxX / GRID); i++) {
          const key = this.key(i, j);
          const l = this.cells.get(key);
          if (l === undefined) this.cells.set(key, [a.index]);
          else l.push(a.index);
        }
      }
    }
    // Portals: edge e of area A with each connection's target B: the part of A's edge B's polygon touches.
    json.areas.forEach((raw, ai) => {
      const a = this.areas[ai] as Area;
      const edges = raw[3];
      const n = a.xs.length;
      for (let e = 0; e < n && e < edges.length; e++) {
        const ax = a.xs[e] as number;
        const ay = a.ys[e] as number;
        const bx = a.xs[(e + 1) % n] as number;
        const by = a.ys[(e + 1) % n] as number;
        for (const toId of edges[e] as readonly number[]) {
          const bi = byId.get(toId);
          if (bi === undefined) continue;
          const b = this.areas[bi] as Area;
          const p = this.portal(a, b, ax, ay, bx, by);
          if (p !== null) a.portals.push(p);
        }
      }
    });
  }

  static fromJson(json: unknown, info: MapInfo | null): Cs2Nav {
    const j = (typeof json === 'string' ? JSON.parse(json) : json) as Cs2NavJson;
    if (typeof j !== 'object' || j === null || !Array.isArray(j.areas) || !Array.isArray(j.corners)) throw new Cs2NavError('nav.json: malformed');
    return new Cs2Nav(j, info);
  }

  get areaCount(): number {
    return this.areas.length;
  }

  /** Counts of usable links by kind (docs, tests). */
  linkStats(): Record<LinkKind, number> {
    const out: Record<LinkKind, number> = { walk: 0, drop: 0, jump: 0 };
    for (const a of this.areas) for (const p of a.portals) out[p.kind]++;
    return out;
  }

  private key(i: number, j: number): number {
    return (j - this.gy0) * 100003 + (i - this.gx0);
  }

  private portal(a: Area, b: Area, ax: number, ay: number, bx: number, by: number): Portal | null {
    // The interval of A's edge (t in [0, 1]) that lies on B's boundary: B's corners projected onto the edge line,
    // kept if within 1 unit of it.
    const dx = bx - ax;
    const dy = by - ay;
    const len2 = dx * dx + dy * dy;
    if (len2 < 1e-9) return null;
    const len = Math.sqrt(len2);
    let t0 = Infinity;
    let t1 = -Infinity;
    const m = b.xs.length;
    for (let k = 0; k < m; k++) {
      const px = b.xs[k] as number;
      const py = b.ys[k] as number;
      const off = Math.abs(cross(ax, ay, bx, by, px, py)) / len;
      if (off > 1) continue;
      const t = ((px - ax) * dx + (py - ay) * dy) / len2;
      t0 = Math.min(t0, t);
      t1 = Math.max(t1, t);
    }
    if (!(t1 > t0)) {
      // No corner of B on A's edge (B touches it inside one of its own edges): the whole edge.
      t0 = 0;
      t1 = 1;
    }
    t0 = Math.max(0, t0);
    t1 = Math.min(1, t1);
    if (!(t1 > t0)) return null;
    const plen = (t1 - t0) * len;
    const inset = Math.min(PORTAL_INSET, plen / 2) / len;
    const s0 = t0 + inset;
    const s1 = t1 - inset;
    const qx0 = ax + dx * s0;
    const qy0 = ay + dy * s0;
    const qx1 = ax + dx * s1;
    const qy1 = ay + dy * s1;
    const mx = (qx0 + qx1) / 2;
    const my = (qy0 + qy1) / 2;
    const zFrom = polyZ(a, mx, my);
    const zTo = polyZ(b, mx, my);
    const dz = zTo - zFrom;
    // How far the far side is from the portal (0 when the areas share the edge): a jump spans little.
    const near = closestOnPoly(b, mx, my);
    const reach = Math.hypot(near.x - mx, near.y - my);
    let kind: LinkKind = 'walk';
    if (dz > STEP_UP) {
      if (dz > JUMP_UP || reach > JUMP_REACH) return null;
      kind = 'jump';
    } else if (dz < -STEP_UP) {
      kind = 'drop';
    }
    return { to: b.index, kind, ax: qx0, ay: qy0, bx: qx1, by: qy1, mx, my, zFrom, zTo };
  }

  private inside(a: Area, x: number, y: number): boolean {
    if (x < a.minX - INSIDE_EPS || x > a.maxX + INSIDE_EPS || y < a.minY - INSIDE_EPS || y > a.maxY + INSIDE_EPS) return false;
    const n = a.xs.length;
    // Convex polygon, either winding: all edge cross products on one side (within eps × edge length).
    let pos = false;
    let neg = false;
    for (let k = 0; k < n; k++) {
      const ax = a.xs[k] as number;
      const ay = a.ys[k] as number;
      const bx = a.xs[(k + 1) % n] as number;
      const by = a.ys[(k + 1) % n] as number;
      const c = cross(ax, ay, bx, by, x, y);
      const l = Math.hypot(bx - ax, by - ay);
      if (c > INSIDE_EPS * l) pos = true;
      else if (c < -INSIDE_EPS * l) neg = true;
      if (pos && neg) return false;
    }
    return true;
  }

  private candidates(x: number, y: number): readonly number[] {
    return this.cells.get(this.key(Math.floor(x / GRID), Math.floor(y / GRID))) ?? [];
  }

  /** The area under (x, y) whose floor is nearest to z (any if z is undefined: the lowest index), or null. */
  areaIndexAt(p: { x: number; y: number; z?: number }): number {
    let best = -1;
    let bestD = Infinity;
    for (const i of this.candidates(p.x, p.y)) {
      const a = this.areas[i] as Area;
      if (!this.inside(a, p.x, p.y)) continue;
      if (p.z === undefined) return i;
      const d = Math.abs(polyZ(a, p.x, p.y) - p.z);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    if (best >= 0 && p.z !== undefined && bestD > LEVEL_SLACK) return -1;
    return best;
  }

  /** Area id at a point (debug). */
  areaIdAt(p: { x: number; y: number; z?: number }): number | null {
    const i = this.areaIndexAt(p);
    return i < 0 ? null : (this.areas[i] as Area).id;
  }

  /** Area flags at a point (0 off the mesh). */
  flagsAt(p: { x: number; y: number; z?: number }): number {
    const i = this.areaIndexAt(p);
    return i < 0 ? 0 : (this.areas[i] as Area).flags;
  }

  isWalkable(p: { x: number; y: number; z?: number }): boolean {
    return this.areaIndexAt(p) >= 0;
  }

  /** The nearest point on the nearest area (3D distance, z weighted ×2), or the point itself when walkable. */
  private nearest(p: { x: number; y: number; z?: number }): { index: number; x: number; y: number; z: number } {
    const at = this.areaIndexAt(p);
    if (at >= 0) return { index: at, x: p.x, y: p.y, z: polyZ(this.areas[at] as Area, p.x, p.y) };
    let best: { index: number; x: number; y: number; z: number } | null = null;
    let bestD = Infinity;
    const ci = Math.floor(p.x / GRID);
    const cj = Math.floor(p.y / GRID);
    const seen = new Set<number>();
    for (let r = 0; r < 64; r++) {
      for (let j = cj - r; j <= cj + r; j++) {
        for (let i = ci - r; i <= ci + r; i++) {
          if (Math.max(Math.abs(i - ci), Math.abs(j - cj)) !== r) continue;
          for (const k of this.cells.get(this.key(i, j)) ?? []) {
            if (seen.has(k)) continue;
            seen.add(k);
            const a = this.areas[k] as Area;
            const q = closestOnPoly(a, p.x, p.y);
            const z = polyZ(a, q.x, q.y);
            const dz = p.z === undefined ? 0 : (z - p.z) * 2;
            const d = Math.hypot(q.x - p.x, q.y - p.y, dz);
            if (d < bestD || (d === bestD && best !== null && k < best.index)) {
              bestD = d;
              best = { index: k, x: q.x, y: q.y, z };
            }
          }
        }
      }
      // Anything in a further ring is at least (r * GRID) away.
      if (best !== null && bestD <= r * GRID) break;
    }
    if (best === null) throw new Cs2NavError('nav: empty mesh');
    return best;
  }

  /** `p` if walkable (its own z), else the nearest point on the mesh (with that floor's z). */
  snap(p: { x: number; y: number; z?: number }): Vec3 {
    if (this.isWalkable(p)) return { x: p.x, y: p.y, z: p.z ?? this.zAt(p) };
    const q = this.nearest(p);
    return { x: q.x, y: q.y, z: q.z };
  }

  zAt(p: { x: number; y: number; z?: number }): number {
    const i = this.areaIndexAt(p);
    if (i >= 0) return polyZ(this.areas[i] as Area, p.x, p.y);
    return this.nearest(p).z;
  }

  floorsAt(x: number, y: number): number[] {
    const out: number[] = [];
    for (const i of this.candidates(x, y)) {
      const a = this.areas[i] as Area;
      if (this.inside(a, x, y)) out.push(polyZ(a, x, y));
    }
    return out.sort((p, q) => q - p);
  }

  /** 2D: every 8 units of the segment lies over some area (any level). Grenade throws and the 2D sight fallback. */
  lineOfSight(a: { x: number; y: number }, b: { x: number; y: number }): boolean {
    const len = Math.hypot(b.x - a.x, b.y - a.y);
    const n = Math.max(1, Math.ceil(len / 8));
    for (let k = 0; k <= n; k++) {
      const x = a.x + ((b.x - a.x) * k) / n;
      const y = a.y + ((b.y - a.y) * k) / n;
      if (this.areaIndexAt({ x, y }) < 0) return false;
    }
    return true;
  }

  /**
   * A straight walk from a to b on the mesh: every `WALK_SAMPLE` units the line is over an area whose floor is at
   * most a step above the floor at the previous sample (any step down that a connection of the previous area allows:
   * walking off a ledge), starting on a's area and ending on b's level.
   */
  segmentWalkable(a: { x: number; y: number; z?: number }, b: { x: number; y: number; z?: number }): boolean {
    let cur = this.areaIndexAt(a);
    if (cur < 0) return false;
    let z = polyZ(this.areas[cur] as Area, a.x, a.y);
    const len = Math.hypot(b.x - a.x, b.y - a.y);
    const n = Math.max(1, Math.ceil(len / WALK_SAMPLE));
    let gap = 0;
    for (let k = 1; k <= n; k++) {
      const x = a.x + ((b.x - a.x) * k) / n;
      const y = a.y + ((b.y - a.y) * k) / n;
      const here = this.areas[cur] as Area;
      if (gap === 0 && this.inside(here, x, y)) {
        z = polyZ(here, x, y);
        continue;
      }
      let next = -1;
      let nextZ = 0;
      let bestDz = Infinity;
      for (const i of this.candidates(x, y)) {
        const c = this.areas[i] as Area;
        if (!this.inside(c, x, y)) continue;
        const cz = polyZ(c, x, y);
        const dz = cz - z;
        if (dz > STEP_UP) continue;
        // Lower than a step, or across a gap: only through a connection of the area we are leaving (a drop).
        if ((dz < -STEP_UP || gap > 0) && !here.portals.some((p) => p.to === i)) continue;
        if (Math.abs(dz) < bestDz) {
          bestDz = Math.abs(dz);
          next = i;
          nextZ = cz;
        }
      }
      if (next < 0) {
        // Off the mesh: a drop's gap between a ledge and the floor below is crossed if it is short.
        gap += len / n;
        if (gap > DROP_GAP) return false;
        continue;
      }
      gap = 0;
      cur = next;
      z = nextZ;
    }
    if (gap > 0) return false;
    return b.z === undefined || Math.abs(z - b.z) <= LEVEL_SLACK;
  }

  /** Was this path point the far end of a jump link? (The AI jumps toward it.) */
  isJumpPoint(p: { x: number; y: number }): boolean {
    return this.jumpPoints.has(`${p.x},${p.y}`);
  }

  /** The area at p asks for a crouch (CrouchHeight). */
  isCrouchAt(p: { x: number; y: number; z?: number }): boolean {
    return (this.flagsAt(p) & NAV_CROUCH) !== 0;
  }

  /** A* + funnel (module comment). null if b can't be reached from a. */
  path(a: { x: number; y: number; z?: number }, b: { x: number; y: number; z?: number }): Vec3[] | null {
    const sa = this.nearest(a);
    const sb = this.nearest(b);
    const n = this.areas.length;
    const g = new Float64Array(n).fill(Infinity);
    const ex = new Float64Array(n);
    const ey = new Float64Array(n);
    const ez = new Float64Array(n);
    const parent = new Int32Array(n).fill(-1);
    const via = new Int32Array(n).fill(-1);
    const closed = new Uint8Array(n);
    const heap = new Heap();
    g[sa.index] = 0;
    ex[sa.index] = sa.x;
    ey[sa.index] = sa.y;
    ez[sa.index] = sa.z;
    heap.push(Math.hypot(sb.x - sa.x, sb.y - sa.y, sb.z - sa.z), sa.index);
    let found = false;
    while (heap.size > 0) {
      const cur = heap.pop();
      if (closed[cur] === 1) continue;
      closed[cur] = 1;
      if (cur === sb.index) {
        found = true;
        break;
      }
      const area = this.areas[cur] as Area;
      const gc = g[cur] as number;
      area.portals.forEach((p, pi) => {
        if (closed[p.to] === 1) return;
        const ng = gc + Math.hypot(p.mx - (ex[cur] as number), p.my - (ey[cur] as number), p.zFrom - (ez[cur] as number)) + Math.abs(p.zTo - p.zFrom) + (p.kind === 'jump' ? JUMP_COST : 0);
        if (ng < (g[p.to] as number) - 1e-9) {
          g[p.to] = ng;
          ex[p.to] = p.mx;
          ey[p.to] = p.my;
          ez[p.to] = p.zTo;
          parent[p.to] = cur;
          via[p.to] = pi;
          heap.push(ng + Math.hypot(sb.x - p.mx, sb.y - p.my, sb.z - p.zTo), p.to);
        }
      });
    }
    if (!found) return null;
    const chain: number[] = [];
    for (let id = sb.index; id !== -1; id = parent[id] as number) chain.push(id);
    chain.reverse();
    // Portals along the corridor, oriented left/right for the funnel.
    const portals: { lx: number; ly: number; rx: number; ry: number; jump: boolean; from: number; to: number }[] = [];
    for (let k = 1; k < chain.length; k++) {
      const to = chain[k] as number;
      const from = chain[k - 1] as number;
      const p = (this.areas[from] as Area).portals[via[to] as number] as Portal;
      portals.push({ lx: p.ax, ly: p.ay, rx: p.bx, ry: p.by, jump: p.kind === 'jump', from, to });
    }
    // Funnel per segment between forced (jump) waypoints.
    const out: Vec3[] = [{ x: roundNumber(sa.x), y: roundNumber(sa.y), z: roundNumber(sa.z) }];
    let startX = sa.x;
    let startY = sa.y;
    let startArea = sa.index;
    let seg: typeof portals = [];
    const flush = (endX: number, endY: number): void => {
      for (const q of funnel(startX, startY, startArea, seg, endX, endY)) {
        const z = this.zOnCorridor(q.x, q.y, q.area);
        out.push({ x: roundNumber(q.x), y: roundNumber(q.y), z: roundNumber(z) });
      }
    };
    for (const p of portals) {
      if (!p.jump) {
        seg.push(p);
        continue;
      }
      const mx = (p.lx + p.rx) / 2;
      const my = (p.ly + p.ry) / 2;
      flush(mx, my);
      // The waypoint sits on the near side; the next one is the landing just past the portal on the far side.
      out.pop();
      const near: Vec3 = { x: roundNumber(mx), y: roundNumber(my), z: roundNumber(polyZ(this.areas[p.from] as Area, mx, my)) };
      out.push(near);
      const to = this.areas[p.to] as Area;
      const edge = closestOnPoly(to, mx, my);
      const land = stepInto(to, edge.x, edge.y, 12);
      const lp: Vec3 = { x: roundNumber(land.x), y: roundNumber(land.y), z: roundNumber(polyZ(to, land.x, land.y)) };
      this.jumpPoints.add(`${lp.x},${lp.y}`);
      out.push(lp);
      startX = lp.x;
      startY = lp.y;
      startArea = p.to;
      seg = [];
    }
    flush(sb.x, sb.y);
    // The last point is the goal itself (with the asked z when it was on the mesh).
    const last = out[out.length - 1] as Vec3;
    if (b.z !== undefined && this.isWalkable(b) && last.x === roundNumber(sb.x) && last.y === roundNumber(sb.y)) out[out.length - 1] = { x: last.x, y: last.y, z: roundNumber(b.z) };
    return dedupe(out);
  }

  /** z at a funnel vertex: the corridor area it belongs to (portal points: the far side's). */
  private zOnCorridor(x: number, y: number, area: number): number {
    return polyZ(this.areas[area] as Area, x, y);
  }

  /** Total 2D length of a path. */
  static pathLength(points: readonly { x: number; y: number }[]): number {
    let len = 0;
    for (let i = 1; i < points.length; i++) len += Math.hypot((points[i] as Vec3).x - (points[i - 1] as Vec3).x, (points[i] as Vec3).y - (points[i - 1] as Vec3).y);
    return len;
  }

  /**
   * The nearest way out of a blast (docs/ai.md "The bomb's blast"): Dijkstra over areas from the pawn's, costs between
   * portal midpoints; the first area with a candidate (its centroid, or a corner pulled 16 units toward it) at least
   * `clear` (3D) from the bomb; of those, the one nearest to where the walk enters it. Ties by area index.
   */
  escapeSpot(from: Vec3, bomb: Vec3, clear: number): Vec3 | null {
    const d3 = (p: Vec3): number => Math.hypot(p.x - bomb.x, p.y - bomb.y, p.z - bomb.z);
    if (d3(from) >= clear) return { x: from.x, y: from.y, z: from.z };
    const n = this.areas.length;
    const g = new Float64Array(n).fill(Infinity);
    const ex = new Float64Array(n);
    const ey = new Float64Array(n);
    const closed = new Uint8Array(n);
    const s = this.nearest(from);
    g[s.index] = 0;
    ex[s.index] = from.x;
    ey[s.index] = from.y;
    const heap = new Heap();
    heap.push(0, s.index);
    while (heap.size > 0) {
      const cur = heap.pop();
      if (closed[cur] === 1) continue;
      closed[cur] = 1;
      const a = this.areas[cur] as Area;
      const cands: { x: number; y: number }[] = [{ x: a.cx, y: a.cy }];
      for (let k = 0; k < a.xs.length; k++) {
        const vx = a.xs[k] as number;
        const vy = a.ys[k] as number;
        const l = Math.hypot(a.cx - vx, a.cy - vy);
        const f = l > 16 ? 16 / l : 0.5;
        cands.push({ x: vx + (a.cx - vx) * f, y: vy + (a.cy - vy) * f });
      }
      let pick: Vec3 | null = null;
      let pickD = Infinity;
      for (const c of cands) {
        const p: Vec3 = { x: roundNumber(c.x), y: roundNumber(c.y), z: roundNumber(polyZ(a, c.x, c.y)) };
        if (d3(p) < clear) continue;
        const d = Math.hypot(p.x - (ex[cur] as number), p.y - (ey[cur] as number));
        if (d < pickD - 1e-9) {
          pickD = d;
          pick = p;
        }
      }
      if (pick !== null) return pick;
      for (const p of a.portals) {
        if (closed[p.to] === 1) continue;
        const ng = (g[cur] as number) + Math.hypot(p.mx - (ex[cur] as number), p.my - (ey[cur] as number));
        if (ng < (g[p.to] as number) - 1e-9) {
          g[p.to] = ng;
          ex[p.to] = p.mx;
          ey[p.to] = p.my;
          heap.push(ng, p.to);
        }
      }
    }
    return null;
  }

  // ---- map knowledge (map.json) ---------------------------------------------------------------------------

  inBombsite(p: Vec3): boolean {
    return this.info !== null && bombsiteAt(this.info, p) !== null;
  }

  /** The plant spot of the bomb site nearest to p (2D distance to its rects; ties by order), on the mesh. */
  bombsitePoint(p: { x: number; y: number }): Vec3 | null {
    if (this.info === null) return null;
    let best: MapInfo['bombsites'][number] | null = null;
    let bestD = Infinity;
    for (const s of this.info.bombsites) {
      for (const r of s.rects) {
        const d = Math.hypot(Math.max(r.x1 - p.x, 0, p.x - r.x2), Math.max(r.y1 - p.y, 0, p.y - r.y2));
        if (d < bestD - 1e-9) {
          bestD = d;
          best = s;
        }
      }
    }
    return best === null ? null : this.snap(best.plant);
  }

  /** The mean of a team's spawn points, on the mesh. */
  spawnCentre(team: Team): Vec3 | null {
    const s = this.info?.spawns[team] ?? [];
    if (s.length === 0) return null;
    let x = 0;
    let y = 0;
    let z = 0;
    for (const q of s) {
      x += q.x;
      y += q.y;
      z += q.z;
    }
    return this.snap({ x: x / s.length, y: y / s.length, z: z / s.length });
  }
}

/** Height of a convex polygon's plane piece under (x, y) (fan from corner 0; clamped to the nearest piece outside). */
function polyZ(a: Pick<Area, 'xs' | 'ys' | 'zs'>, x: number, y: number): number {
  const n = a.xs.length;
  const x0 = a.xs[0] as number;
  const y0 = a.ys[0] as number;
  const z0 = a.zs[0] as number;
  let bestZ = z0;
  let bestOut = Infinity;
  for (let k = 1; k + 1 < n; k++) {
    const x1 = a.xs[k] as number;
    const y1 = a.ys[k] as number;
    const x2 = a.xs[k + 1] as number;
    const y2 = a.ys[k + 1] as number;
    const det = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
    if (Math.abs(det) < 1e-12) continue;
    const u = ((x - x0) * (y2 - y0) - (x2 - x0) * (y - y0)) / det;
    const v = ((x1 - x0) * (y - y0) - (x - x0) * (y1 - y0)) / det;
    const z = z0 + u * ((a.zs[k] as number) - z0) + v * ((a.zs[k + 1] as number) - z0);
    const out = Math.max(0, -u) + Math.max(0, -v) + Math.max(0, u + v - 1);
    if (out < bestOut) {
      bestOut = out;
      bestZ = z;
      if (out === 0) break;
    }
  }
  return bestZ;
}

function closestOnSeg(ax: number, ay: number, bx: number, by: number, px: number, py: number): { x: number; y: number } {
  const dx = bx - ax;
  const dy = by - ay;
  const l2 = dx * dx + dy * dy;
  const t = l2 === 0 ? 0 : Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / l2));
  return { x: ax + dx * t, y: ay + dy * t };
}

/** The closest point of a convex polygon to (px, py) (pulled 1 unit toward its centroid when on the boundary). */
function closestOnPoly(a: Area, px: number, py: number): { x: number; y: number } {
  let best = { x: a.cx, y: a.cy };
  let bestD = Infinity;
  const n = a.xs.length;
  for (let k = 0; k < n; k++) {
    const q = closestOnSeg(a.xs[k] as number, a.ys[k] as number, a.xs[(k + 1) % n] as number, a.ys[(k + 1) % n] as number, px, py);
    const d = Math.hypot(q.x - px, q.y - py);
    if (d < bestD) {
      bestD = d;
      best = q;
    }
  }
  const l = Math.hypot(a.cx - best.x, a.cy - best.y);
  if (l > 1e-9) {
    const f = Math.min(1, l / 2) / l;
    return { x: best.x + (a.cx - best.x) * f, y: best.y + (a.cy - best.y) * f };
  }
  return best;
}

/** A point `d` units from (x, y) toward the polygon's centroid (the landing past a jump portal). */
function stepInto(a: Area, x: number, y: number, d: number): { x: number; y: number } {
  const l = Math.hypot(a.cx - x, a.cy - y);
  if (l <= d) return { x: a.cx, y: a.cy };
  return { x: x + ((a.cx - x) * d) / l, y: y + ((a.cy - y) * d) / l };
}

/**
 * Simple stupid funnel (Mononen) from (sx, sy) through the portals to (gx, gy): the taut path's vertices after the
 * start, each with the corridor area it lies in. Portals are oriented here (left/right as seen walking through).
 */
function funnel(sx: number, sy: number, startArea: number, portals: readonly { lx: number; ly: number; rx: number; ry: number; to: number; from: number }[], gx: number, gy: number): { x: number; y: number; area: number }[] {
  const pts: { lx: number; ly: number; rx: number; ry: number; area: number }[] = [];
  let px = sx;
  let py = sy;
  for (const p of portals) {
    // Orient: left is the end on the left of the walking direction (from the previous point toward the midpoint).
    const mx = (p.lx + p.rx) / 2;
    const my = (p.ly + p.ry) / 2;
    const c = cross(px, py, mx, my, p.lx, p.ly);
    // A portal lies on the near area's edge: its corners take that area's floor.
    if (c >= 0) pts.push({ lx: p.lx, ly: p.ly, rx: p.rx, ry: p.ry, area: p.from });
    else pts.push({ lx: p.rx, ly: p.ry, rx: p.lx, ry: p.ly, area: p.from });
    px = mx;
    py = my;
  }
  const lastArea = portals.length > 0 ? (portals[portals.length - 1] as { to: number }).to : startArea;
  pts.push({ lx: gx, ly: gy, rx: gx, ry: gy, area: lastArea });
  const out: { x: number; y: number; area: number }[] = [];
  let ax = sx;
  let ay = sy;
  let lx = sx;
  let ly = sy;
  let rx = sx;
  let ry = sy;
  let li = 0;
  let ri = 0;
  for (let i = 0; i < pts.length; i++) {
    const p = pts[i] as (typeof pts)[number];
    // Right side: a new right point that moves the funnel inward (to the left of apex → right)...
    if (cross(ax, ay, rx, ry, p.rx, p.ry) >= 0) {
      // ... tightens it unless it crosses the left side (then the left point is a corner of the path).
      if ((ax === rx && ay === ry) || cross(ax, ay, lx, ly, p.rx, p.ry) < 0) {
        rx = p.rx;
        ry = p.ry;
        ri = i;
      } else {
        out.push({ x: lx, y: ly, area: (pts[li] as (typeof pts)[number]).area });
        ax = lx;
        ay = ly;
        rx = ax;
        ry = ay;
        ri = li;
        i = li;
        continue;
      }
    }
    // Left side, mirrored.
    if (cross(ax, ay, lx, ly, p.lx, p.ly) <= 0) {
      if ((ax === lx && ay === ly) || cross(ax, ay, rx, ry, p.lx, p.ly) > 0) {
        lx = p.lx;
        ly = p.ly;
        li = i;
      } else {
        out.push({ x: rx, y: ry, area: (pts[ri] as (typeof pts)[number]).area });
        ax = rx;
        ay = ry;
        lx = ax;
        ly = ay;
        li = ri;
        i = ri;
        continue;
      }
    }
  }
  out.push({ x: gx, y: gy, area: lastArea });
  return out;
}

function dedupe(points: Vec3[]): Vec3[] {
  const out: Vec3[] = [];
  for (const p of points) {
    const q = out[out.length - 1];
    if (q !== undefined && Math.abs(q.x - p.x) < 1e-6 && Math.abs(q.y - p.y) < 1e-6) continue;
    out.push(p);
  }
  return out;
}
